/* Resoluciones judiciales que citan cada sentencia destacada.

   Archivo generado: no se edita a mano. Sale de la base de jurisprudencia
   de la firma (textos de Nexus y Globalex): se buscó el número de la
   sentencia en todas sus grafías, se leyó el texto íntegro de cada
   resultado para confirmar que la cita es de esta sentencia (se descartan
   votos homónimos de otros despachos) y se contó cada resolución una vez,
   uniendo sentencia y extracto por despacho, número y expediente. El
   identificador de Nexus apunta a la sentencia íntegra («sen-»). */

export type ResolucionQueCita = {
  /** AAAA-MM-DD */
  fecha: string;
  numero: string;
  /** Con la sección, si la tiene. */
  despacho: string;
  /** El despacho sin la sección: la unidad del recuento de despachos. */
  tribunal: string;
  grupo: string;
  expediente?: string;
  nexusId?: string;
};

/** Orden de los grupos en el gráfico: de más a menos citas, «Otros» al final. */
